original=m._require_equal
def first(a,b,path='root'):
 if type(a)!=type(b):return [path,type(a).__name__,type(b).__name__]
 if isinstance(a,dict):
  if a.keys()!=b.keys():return [path,list(a),list(b)]
  for key in a:
   if a[key]!=b[key]:return first(a[key],b[key],path+'.'+key)
 elif isinstance(a,list):
  if len(a)!=len(b):return [path,'length',len(a),len(b)]
  for index,(x,y) in enumerate(zip(a,b)):
   if x!=y:return first(x,y,path+f'[{index}]')
 return [path,a,b]
def diagnostic(a,b,description):
 try:original(a,b,description)
 except ValueError:
